"""scripts/generate_macros_r1.py
Gera macros LaTeX para os resultados R1 (Fase D).
Lê results/r1/r1_decisions.json e results/r1/r1_aggregate.csv.
Escreve results/r1/macros_r1.tex.
"""
import json
from pathlib import Path

ROOT = Path(__file__).parent.parent
R1   = ROOT / "results" / "r1"

dec  = json.loads((R1/"r1_decisions.json").read_text())

import pandas as pd
agg = pd.read_csv(R1/"r1_aggregate.csv")

def q(cell, kappa, asm):
    r = agg[(agg.cell==cell)&(agg.kappa==kappa)&(agg.assembly==asm)]
    return round(float(r.Q2.iloc[0]),1) if len(r) else "??"

lines = [
    "% AUTO-GENERATED by scripts/generate_macros_r1.py",
    "% Fase D outputs — DO NOT EDIT BY HAND",
    "",
    "% R1-3: diagonal cells (consistent coding)",
    f"\\newcommand{{\\RoneThreeRVstarAprime}}{{{q('RV_star_Aprime',200,'optimal')}}}  % Ncand/A' consistent, opt",
    f"\\newcommand{{\\RoneThreeRMAprime}}{{{q('RM_Aprime',200,'optimal')}}}  % Nvia/A' control, opt",
    f"\\newcommand{{\\RoneThreeRVstarA}}{{{q('RV_star_A',200,'optimal')}}}  % Ncand/A consistent, opt",
    f"\\newcommand{{\\RoneThreeRMA}}{{{q('RM_A',200,'optimal')}}}  % Nvia/A, opt",
    "",
    "% R1-1: Δ_ref optimal (OBSERVAÇÃO: 0 pp)",
    f"\\newcommand{{\\RoneOneOptDelta}}{{{dec['R1-1']['delta_pp']:.1f}}}  % pp",
    f"\\newcommand{{\\RoneOneOptDecision}}{{{dec['R1-1']['decision']}}}",
    "",
    "% R1-2: Δ_ref greedy (EFEITO: +11.8 pp)",
    f"\\newcommand{{\\RoneTwoGrdDelta}}{{{dec['R1-2']['delta_pp']:.1f}}}  % pp",
    f"\\newcommand{{\\RoneTwoGrdCIlo}}{{{dec['R1-2']['ci_lo']:.1f}}}",
    f"\\newcommand{{\\RoneTwoGrdCIhi}}{{{dec['R1-2']['ci_hi']:.1f}}}",
    "",
    "% R1-5: R-asp descriptive",
    f"\\newcommand{{\\RaspOptimal}}{{{dec['R1-5']['R_asp_opt']:.1f}}}  % %",
    f"\\newcommand{{\\RaspGreedy}}{{{dec['R1-5']['R_asp_grd']:.1f}}}  % %",
    "",
    "% R1-6: residual ref-set effect",
    f"\\newcommand{{\\ResidualRefOptDelta}}{{{dec['R1-6']['delta_pp']:.1f}}}  % pp",
    f"\\newcommand{{\\ResidualRefOptCIlo}}{{{dec['R1-6']['ci_lo']:.1f}}}",
    f"\\newcommand{{\\ResidualRefOptCIhi}}{{{dec['R1-6']['ci_hi']:.1f}}}",
    "",
    "% Greedy improvement with consistent coding",
    f"\\newcommand{{\\GreedyRefSetImprovement}}{{{dec['R1-2']['delta_pp']:.1f}}}  % pp: RV_star_Aprime grd - RM_Aprime grd",
]

out = "\n".join(lines) + "\n"
(R1/"macros_r1.tex").write_text(out, encoding="utf-8")
print(out)
print(f"Saved: {R1}/macros_r1.tex")
